{
  "name": "@frank_lee/jz-oc-plugin",
  "version": "2.0.1",
  "description": "OpenCode plugin: dynamically load models from an OpenAI-compatible AIGW gateway, enriched with cost/reasoning from the models.opencode.ai catalog.",
  "type": "module",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "engines": {
    "opencode": ">=1.18.0"
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.json && node scripts/stamp-pack-time.mjs",
    "test": "bun test tests"
  },
  "keywords": [
    "opencode",
    "plugin",
    "aigw",
    "models",
    "provider",
    "openai-compatible"
  ],
  "license": "MIT",
  "devDependencies": {
    "@opencode-ai/plugin": "^1.14.29",
    "@types/bun": "^1.4.0",
    "@types/node": "^26.4.0",
    "typescript": "^5.5.0"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.11"
  }
}
